(() => {
'use strict';
const CORE=window.OneBoxReaderEnhancementCore;
const STATS_KEY='onebox.reader-stats', OPDS_KEY='onebox.reader-opds';
let importer=null, currentBook='', lastTick=0, lastActivity=0, lastPersist=0, stats=CORE.normalizeStats(read(STATS_KEY,{})), sources=read(OPDS_KEY,[]);
const DEVICE_KEY='onebox.reader-device-id';
function readerDeviceId(){let id=localStorage.getItem(DEVICE_KEY);if(!id){id=window.crypto?.randomUUID?.()||('device-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));localStorage.setItem(DEVICE_KEY,id)}return id}
const DEVICE_ID=readerDeviceId();
let activeUrl='', feedItems=[], nextUrl='', prevUrl='', feedTitle='', opdsBusy=false;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'')}catch{return fallback}}
function language(){return (localStorage.getItem('onebox.language')||document.documentElement.lang||'zh').startsWith('en')?'en':'zh'}
function tx(zh,en){return language()==='en'?en:zh}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function saveStats(force=false){if(!force&&Date.now()-lastPersist<55000)return;lastPersist=Date.now();stats.updatedAt=Date.now();localStorage.setItem(STATS_KEY,JSON.stringify(CORE.normalizeStats(stats)));window.dispatchEvent(new CustomEvent('onebox:reader-stats-updated'))}
function getBookName(id){try{return(JSON.parse(localStorage.getItem('onebox.library')||'[]').find(x=>x.id===id)||{}).name||tx('已删除的书籍','Removed book')}catch{return tx('书籍','Book')}}
function duration(sec){const s=Math.max(0,Math.floor(sec||0));if(s<60)return s+' '+tx('秒','sec');const m=Math.floor(s/60);if(m<60)return m+' '+tx('分钟','min');const h=Math.floor(m/60);return h+' '+tx('小时','hr')+' '+m%60+' '+tx('分钟','min')}
function dayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function start(bookId){stop();currentBook=String(bookId||'');lastTick=Date.now();lastActivity=lastTick}
function stop(){tick(true);currentBook='';lastTick=0}
function tick(force=false){if(!currentBook)return;const now=Date.now(),elapsed=Math.max(0,Math.min(30,Math.floor((now-lastTick)/1000)));lastTick=now;if(!document.hidden&&now-lastActivity<120000&&elapsed){stats=CORE.addSeconds(stats,dayKey(),currentBook,elapsed,DEVICE_ID);saveStats(force)}}
['pointerdown','touchstart','keydown','wheel'].forEach(type=>document.addEventListener(type,()=>{if(currentBook)lastActivity=Date.now()},{passive:true,capture:true}));
document.addEventListener('visibilitychange',()=>{if(document.hidden)tick(true);else if(currentBook){lastTick=Date.now();lastActivity=Date.now()}});
window.addEventListener('pagehide',()=>tick(true));
setInterval(()=>tick(false),15000);
function actionsMarkup(){return '<button type="button" class="reader-extra-action" data-reader-stats>'+tx('统计','Stats')+'</button><button type="button" class="reader-extra-action" data-reader-opds>OPDS</button>'}
function modalShell(title,body){closeModal();const node=document.createElement('div');node.className='reader-extra-overlay';node.dataset.readerExtraOverlay='';node.innerHTML='<section class="reader-extra-dialog" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><header><strong>'+esc(title)+'</strong><button type="button" data-extra-close aria-label="'+tx('关闭','Close')+'">×</button></header><div class="reader-extra-body">'+body+'</div></section>';document.body.append(node);return node}
function closeModal(){document.querySelector('[data-reader-extra-overlay]')?.remove()}
function renderStats(){
stats=CORE.normalizeStats(read(STATS_KEY,stats));const aggregate=CORE.aggregateStats(stats),today=dayKey(),days=CORE.recentDays(new Date(),35),total=aggregate.total,activeDays=Object.values(aggregate.days).filter(x=>x>0).length;
const squares=days.map(d=>{const value=aggregate.days[d]||0;const level=value===0?0:value<300?1:value<1200?2:value<3600?3:4;return '<i title="'+d+' · '+duration(value)+'" data-level="'+level+'"></i>'}).join('');
const top=Object.entries(aggregate.books).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([id,seconds])=>'<li><span>'+esc(getBookName(id))+'</span><b>'+duration(seconds)+'</b></li>').join('');
const body='<div class="reader-stats-summary"><article><small>'+tx('累计阅读','Total reading')+'</small><strong>'+duration(total)+'</strong></article><article><small>'+tx('阅读天数','Reading days')+'</small><strong>'+activeDays+'</strong></article><article><small>'+tx('今天','Today')+'</small><strong>'+duration(aggregate.days[today]||0)+'</strong></article></div><h3>'+tx('最近 5 周','Last 5 weeks')+'</h3><div class="reader-stats-heatmap">'+squares+'</div><div class="reader-stats-legend"><span>'+tx('少','Less')+'</span><i data-level="0"></i><i data-level="1"></i><i data-level="2"></i><i data-level="3"></i><i data-level="4"></i><span>'+tx('多','More')+'</span></div><h3>'+tx('阅读最多','Top books')+'</h3><ol class="reader-stats-books">'+(top||'<li>'+tx('还没有阅读记录','No reading sessions yet')+'</li>')+'</ol>';
modalShell(tx('阅读统计','Reading statistics'),body);
}
function sourceList(){return Array.isArray(sources)?sources.filter(s=>s&&s.url):[]}
function renderOPDS(items=feedItems,title=feedTitle){
const list=sourceList();const opts=list.map((s,i)=>'<option value="'+i+'" '+(s.url===activeUrl?'selected':'')+'>'+esc(s.name||s.url)+'</option>').join('');
const entries=(items||[]).map((item,i)=>'<article class="reader-opds-entry"><div><strong>'+esc(item.title||tx('未命名','Untitled'))+'</strong>'+(item.author?'<small>'+esc(item.author)+'</small>':'')+(item.summary?'<p>'+esc(item.summary).slice(0,260)+'</p>':'')+'</div>'+(item.url?'<button type="button" data-opds-open="'+i+'">'+tx('打开','Open')+'</button>':'')+(item.acquisition?'<button type="button" data-opds-download="'+i+'" '+(opdsBusy?'disabled':'')+'>'+tx('加入书架','Add to shelf')+'</button>':'')+'</article>').join('');
const body='<div class="reader-opds-source-row"><input type="url" id="readerOpdsUrl" placeholder="https://…/opds" value="'+esc(activeUrl)+'"><button type="button" data-opds-add>'+tx('添加书源','Add source')+'</button></div><div class="reader-opds-source-row"><select id="readerOpdsSource"><option value="">'+tx('选择已保存的书源','Choose a saved catalog')+'</option>'+opts+'</select><button type="button" data-opds-load>'+tx('浏览','Browse')+'</button></div><form class="reader-opds-search" data-opds-search><input type="search" id="readerOpdsQuery" placeholder="'+tx('搜索书源（支持目录搜索链接）','Search catalog (when supported)')+'"><button type="submit">'+tx('搜索','Search')+'</button></form><div class="reader-opds-heading">'+esc(title||tx('书源目录','OPDS catalog'))+'</div><div class="reader-opds-list">'+(entries||'<p class="reader-opds-empty">'+tx('添加书源或选择已保存的书源开始浏览。部分站点需支持跨域访问。','Add a catalog to browse. The server must allow cross-origin requests.')+'</p>')+'</div><div class="reader-opds-pagination">'+(prevUrl?'<button data-opds-page="prev">'+tx('上一页','Previous')+'</button>':'')+(nextUrl?'<button data-opds-page="next">'+tx('下一页','Next')+'</button>':'')+'</div><p class="reader-opds-hint">'+tx('书籍下载后保存到本机书架，并沿用现有的阅读进度与云同步。受版权保护或 DRM 文件无法在浏览器中解密。','Downloaded books are stored in the local shelf and use existing progress and cloud sync. DRM-protected files cannot be decrypted in the browser.')+'</p>';
modalShell('OPDS',body);
}
function parseFeed(xml,base){
const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw Error(tx('书源返回的 XML 无法解析','The catalog returned invalid XML'));
const children=(el,name)=>Array.from(el.children||[]).filter(x=>x.localName===name);
const first=(el,name)=>children(el,name)[0];
const links=(el)=>children(el,'link').map(l=>({href:CORE.safeTemplateUrl(l.getAttribute('href'),base),rel:l.getAttribute('rel')||'',type:l.getAttribute('type')||'',title:l.getAttribute('title')||''})).filter(x=>x.href);
const entries=children(doc.documentElement,'entry').map(entry=>{const ls=links(entry),title=first(entry,'title')?.textContent?.trim()||'',summary=first(entry,'summary')?.textContent?.trim()||first(entry,'content')?.textContent?.trim()||'',author=first(entry,'author')?.textContent?.trim()||'';const acquisition=ls.find(l=>/acquisition/i.test(l.rel))||ls.find(l=>/epub|pdf|mobi|azw3|fb2|plain/i.test(l.type));const nav=ls.find(l=>/application\/(?:atom\+xml|opds\+json)|opds-catalog/i.test(l.type))||ls.find(l=>/subsection|collection|related/i.test(l.rel));return{title,summary,author,url:nav?.href||'',acquisition:acquisition?.href||'',type:acquisition?.type||'',filename:''}});
const feedLinks=links(doc.documentElement);return{title:first(doc.documentElement,'title')?.textContent?.trim()||'',entries,next:feedLinks.find(l=>l.rel==='next')?.href||'',prev:feedLinks.find(l=>l.rel==='previous')?.href||'',search:feedLinks.find(l=>l.rel==='search')?.href||''};
}
async function loadFeed(url){const safe=CORE.safeHttpUrl(url);if(!safe)throw Error(tx('请输入有效的 HTTP(S) 书源地址','Enter a valid HTTP(S) catalog URL'));activeUrl=safe;opdsBusy=true;renderOPDS([],tx('正在加载…','Loading…'));try{const response=await fetch(safe,{headers:{Accept:'application/atom+xml, application/opds+json, application/json, text/xml, */*'}});if(!response.ok)throw Error('HTTP '+response.status);const type=response.headers.get('content-type')||'';if(/opds\\+json|application\/json/i.test(type)){const data=await response.json();const pubs=data.publications||[];feedItems=pubs.map(p=>{const links=p.links||[];const acq=links.find(l=>/acquisition/i.test(l.rel||''))||links.find(l=>/epub|pdf|mobi|azw3|fb2/i.test(l.type||''));const nav=links.find(l=>/opds|atom/i.test(l.type||''));return{title:p.metadata?.title||'',author:p.metadata?.author?.map?.(a=>a.name||a).join(', ')||'',summary:p.metadata?.description||'',url:nav?CORE.safeHttpUrl(nav.href,safe):'',acquisition:acq?CORE.safeHttpUrl(acq.href,safe):'',type:acq?.type||''}});nextUrl=(data.links||[]).find(l=>l.rel==='next')?CORE.safeHttpUrl((data.links||[]).find(l=>l.rel==='next').href,safe):'';prevUrl=(data.links||[]).find(l=>l.rel==='previous')?CORE.safeHttpUrl((data.links||[]).find(l=>l.rel==='previous').href,safe):'';feedTitle=data.metadata?.title||'OPDS';for(const p of data.navigation||data.catalogs||[])feedItems.push({title:p.title||p.metadata?.title||'',summary:p.summary||'',url:CORE.safeHttpUrl(p.href,safe),acquisition:'',type:p.type||''});}else{const parsed=parseFeed(await response.text(),safe);feedItems=parsed.entries;nextUrl=parsed.next;prevUrl=parsed.prev;feedTitle=parsed.title||'OPDS';if(parsed.search)window.dispatchEvent(new CustomEvent('onebox:opds-search-link',{detail:{href:parsed.search,base:safe}}));}opdsBusy=false;renderOPDS(feedItems,feedTitle)}catch(error){opdsBusy=false;feedItems=[];nextUrl='';renderOPDS([],tx('加载失败：','Could not load: ')+(error.message||tx('请检查书源地址或跨域设置','check URL or CORS settings')))}finally{opdsBusy=false}}
function saveSource(){const input=document.querySelector('#readerOpdsUrl'),url=CORE.safeHttpUrl(input?.value);if(!url){alert(tx('请输入有效的 HTTP(S) 地址','Enter a valid HTTP(S) URL'));return}if(!sourceList().some(s=>s.url===url))sources=[...sourceList(),{name:new URL(url).hostname,url}];localStorage.setItem(OPDS_KEY,JSON.stringify(sources));activeUrl=url;loadFeed(url)}
async function downloadEntry(index){const item=feedItems[Number(index)];if(!item?.acquisition||!importer)return;opdsBusy=true;renderOPDS(feedItems,feedTitle);try{const response=await fetch(item.acquisition,{headers:{Accept:'application/epub+zip, application/pdf, application/x-mobipocket-ebook, application/octet-stream, */*'}});if(!response.ok)throw Error('HTTP '+response.status);const blob=await response.blob();if(blob.size>256*1024*1024)throw Error(tx('文件超过 256 MB 限制','File exceeds the 256 MB limit'));const extFromType={'application/epub+zip':'epub','application/pdf':'pdf','application/x-mobipocket-ebook':'mobi','application/vnd.amazon.ebook':'azw3','application/fb2+zip':'fb2','text/plain':'txt'};let filename='';const disposition=response.headers.get('content-disposition')||'';filename=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1]||disposition.match(/filename="?([^";]+)"?/i)?.[1]||'';try{filename=decodeURIComponent(filename)}catch{}const ext=(item.type.split(';')[0]&&Object.entries(extFromType).find(([mime])=>item.type.includes(mime))?.[1])||item.acquisition.split(/[?#]/)[0].split('.').pop()?.toLowerCase()||'epub';if(!/^(epub|pdf|mobi|azw3|fb2|txt|md|markdown)$/.test(ext))throw Error(tx('书源文件格式暂不支持','Unsupported file format'));if(!filename)filename=(item.title||'OPDS book').replace(/[\\/:*?"<>|]/g,'_')+'.'+ext;if(!filename.toLowerCase().endsWith('.'+ext))filename+='.'+ext;await importer([new File([blob],filename,{type:blob.type||item.type||'application/octet-stream',lastModified:Date.now()})]);closeModal()}catch(error){alert(tx('下载失败：','Download failed: ')+(error.message||tx('请确认站点允许跨域下载','check CORS permissions')))}finally{opdsBusy=false;if(document.querySelector('[data-reader-extra-overlay]'))renderOPDS(feedItems,feedTitle)}}
document.addEventListener('click',event=>{
if(event.target.closest('[data-extra-close]')||event.target.matches('[data-reader-extra-overlay]')){closeModal();return}
if(event.target.closest('[data-reader-stats]')){renderStats();return}
if(event.target.closest('[data-reader-opds]')){activeUrl='';feedItems=[];nextUrl='';renderOPDS();return}
if(event.target.closest('[data-opds-add]')){event.preventDefault();saveSource();return}
if(event.target.closest('[data-opds-load]')){const sel=document.querySelector('#readerOpdsSource'),src=sourceList()[Number(sel?.value)];const url=src?.url||document.querySelector('#readerOpdsUrl')?.value;if(url)loadFeed(url);return}
const open=event.target.closest('[data-opds-open]');if(open){const item=feedItems[Number(open.dataset.opdsOpen)];if(item?.url)loadFeed(item.url);return}
const dl=event.target.closest('[data-opds-download]');if(dl){void downloadEntry(dl.dataset.opdsDownload);return}
const page=event.target.closest('[data-opds-page]');if(page){const url=page.dataset.opdsPage==='next'?nextUrl:prevUrl;if(url)loadFeed(url);return}
});
document.addEventListener('change',event=>{if(event.target.id==='readerOpdsSource'){const src=sourceList()[Number(event.target.value)];if(src){const input=document.querySelector('#readerOpdsUrl');if(input)input.value=src.url;loadFeed(src.url)}}});
document.addEventListener('submit',async event=>{if(!event.target.matches('[data-opds-search]'))return;event.preventDefault();const query=document.querySelector('#readerOpdsQuery')?.value?.trim();if(!query)return;const url=activeUrl;if(!url)return;try{const response=await fetch(url,{headers:{Accept:'application/atom+xml, application/opds+json, application/json, text/xml'}});if(!response.ok)throw Error('HTTP '+response.status);const doc=new DOMParser().parseFromString(await response.text(),'application/xml');const link=Array.from(doc.getElementsByTagNameNS('*','link')).find(l=>l.getAttribute('rel')==='search');const href=link?.getAttribute('href');if(!href){alert(tx('此书源未提供搜索链接','This catalog has no search link'));return}let template=CORE.safeTemplateUrl(href,url);if(!template){alert(tx('搜索地址无效','Invalid search URL'));return}if(/opensearchdescription/i.test(link?.getAttribute('type')||'')){const description=await fetch(template,{headers:{Accept:'application/opensearchdescription+xml, application/xml, text/xml'}});if(!description.ok)throw Error('HTTP '+description.status);const searchDoc=new DOMParser().parseFromString(await description.text(),'application/xml');const searchEntry=Array.from(searchDoc.getElementsByTagName('Url')).find(item=>/atom|opds|json/i.test(item.getAttribute('type')||''));template=CORE.safeTemplateUrl(searchEntry?.getAttribute('template'),template);if(!template)throw Error(tx('书源搜索模板无效','Invalid OpenSearch template'))}const expanded=CORE.expandSearchTemplate(template,query);if(!expanded)throw Error(tx('搜索地址无效','Invalid search URL'));loadFeed(expanded)}catch(error){alert(tx('搜索失败：','Search failed: ')+error.message)}});
window.addEventListener('onebox:reader-session-start',event=>start(event.detail?.bookId));
window.addEventListener('onebox:reader-session-stop',stop);
window.OneBoxReaderExtras={actionsMarkup,setImporter(value){importer=typeof value==='function'?value:null},start,stop,getStats:()=>CORE.normalizeStats(stats)};
})();